float random(vec2 st) {
    return fract(sin(dot(st.xy, vec2(12.9898, 78.233))) * 43758.5453123);
}

void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
    vec2 uv = fragCoord/iResolution.xy;
    float time = iTime;

    // カーテンのテクスチャ
    float curtain = sin(uv.x * 10.0 + sin(uv.y * 5.0 + time * 0.2) * 0.2) * 0.5 + 0.5;

    // 木漏れ日のパターン
    float light = 0.0;
    for (int i = 0; i < 5; i++) {
        vec2 pos = vec2(random(vec2(float(i), 1.0)), random(vec2(float(i), 2.0)));
        float size = random(vec2(float(i), 3.0)) * 0.1 + 0.05;
        light += smoothstep(size, 0.0, length(uv - pos - vec2(sin(time * 1.5 + float(i)) * 0.02, cos(time * 0.7 + float(i)) * 0.02)));
    }

    // 最終的な色の計算
    vec3 color = mix(vec3(0.8, 0.9, 1.0), vec3(1.0, 0.95, 0.8), curtain);
    color += light * vec3(1.0, 0.9, 0.7) * 0.5;

    fragColor = vec4(color, 1.0);
}
